module skid_buffer_core (
    input wire clk,
    input wire rst,
    input wire [7:0] in_data,
    input wire in_valid,
    output wire in_ready,
    output wire [7:0] out_data,
    output reg out_valid,
    input wire out_ready
);

    reg [7:0] head;
    reg [7:0] tail;
    reg [1:0] occupancy;

    wire push;
    wire pop;

    assign in_ready = (occupancy < 2) || out_ready;
    assign out_data = head;

    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            occupancy <= 2'd0;
            out_valid <= 1'b0;
        end else begin
            case ({push, pop})
                2'b10: begin
                    if (occupancy == 0)
                        head <= in_data;
                    else
                        tail <= in_data;
                    occupancy <= occupancy + 1'b1;
                    out_valid <= 1'b1;
                end
                2'b01: begin
                    if (occupancy == 2)
                        head <= tail;
                    occupancy <= occupancy - 1'b1;
                    out_valid <= (occupancy != 1);
                end
                2'b11: begin
                    if (occupancy == 1)
                        head <= in_data;
                    else begin
                        head <= tail;
                        tail <= in_data;
                    end
                    occupancy <= occupancy;
                    out_valid <= (occupancy != 0);
                end
                default: begin
                    occupancy <= occupancy;
                    out_valid <= out_valid;
                end
            endcase
        end
    end

endmodule

